head.b:skin:
/* ============ TOOLS PRO WEB - Royal Blue 2026 ============ */
:root{
  --text: var(--ink);
  --text-secondary: var(--muted);
  --text-muted: var(--muted);
  --border: var(--line);
  --surface: var(--card);
  --surface-2: var(--sky);
  --bg-alt: var(--sky);
  --brand: var(--royal);
  --brand-soft: #E4EDFF;

 --royal:#1E4FD8;--royal-2:#2F6BFF;--sky:#EAF1FF;--bg:#F4F7FF;
 --card:#FFFFFF;--ink:#0E1633;--muted:#5B6B8C;--line:#DBE4FA;
 --chip:#FFFFFF;--shadow:0 10px 30px rgba(30,79,216,.10);
 --shadow-lg:0 18px 50px rgba(30,79,216,.18);
 --grad:linear-gradient(135deg,#1E4FD8 0%,#2F6BFF 45%,#6A4DFF 100%);
 --radius:18px;
}
[data-theme="dark"]{
  --brand-soft: rgba(88,140,255,.16);

 --royal:#4D7DFF;--sky:#0E1A3D;--bg:#070D22;--card:#0F1A3D;
 --ink:#EAF0FF;--muted:#9DB0D8;--line:#1E2C5C;--chip:#12204A;
 --shadow:0 10px 30px rgba(0,0,0,.45);--shadow-lg:0 18px 50px rgba(0,0,0,.6);
}
*{-webkit-box-sizing:border-box;box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scrollbar-color:#2F6BFF #EAF1FF}
::-webkit-scrollbar{width:10px}
::-webkit-scrollbar-track{background:#F0F4FF;border-radius:10px}
::-webkit-scrollbar-thumb{background:#2F6BFF;border-radius:10px;border:2px solid #F0F4FF}
body{font-family:'Manrope',sans-serif;background:var(--bg);color:var(--ink);overflow-x:hidden;line-height:1.6}
h1,h2,h3,.brand,.stat-num{font-family:'Sora',sans-serif}
a{text-decoration:none;color:inherit}
button{border:none;background:none;cursor:pointer;font-family:inherit}
::selection{background:var(--royal);color:#fff}

/* Header */
header.tpw-header{position:sticky;top:0;z-index:100;background:var(--grad);color:#fff;border-bottom:1px solid rgba(255,255,255,.18)}
.nav-wrap{max-width:1280px;margin:0 auto;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:22px;padding:14px 24px}
.logo{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:10px;-ms-flex-negative:0;flex-shrink:0}
.logo-badge{width:44px;height:44px;border-radius:12px;background:rgba(255,255,255,.16);display:grid;place-items:center}
.logo-badge svg{display:block}
.logo-text{font-family:'Sora';font-weight:800;font-size:1.12rem;line-height:1.1;color:#fff;white-space:nowrap}
.logo-text span{display:block;font-size:.62rem;font-weight:700;letter-spacing:.14em;color:rgba(255,255,255,.82);text-transform:uppercase}
.search-box{-webkit-box-flex:1;-ms-flex:1;flex:1;max-width:520px;position:relative;margin:0 auto}
.search-box input{width:100%;padding:12px 18px 12px 46px;border:1.5px solid rgba(255,255,255,.35);border-radius:50px;background:rgba(255,255,255,.14);color:#fff;font:600 .92rem 'Manrope';outline:none}
.search-box input::-webkit-input-placeholder{color:rgba(255,255,255,.72)}
.search-box input::placeholder{color:rgba(255,255,255,.72)}
.search-box input:focus{border-color:rgba(255,255,255,.75);background:rgba(255,255,255,.22)}
.search-box > svg{position:absolute;left:16px;top:50%;-webkit-transform:translateY(-50%);transform:translateY(-50%);width:19px;height:19px;stroke:rgba(255,255,255,.8)}
nav.main-nav{display:-webkit-box;display:-ms-flexbox;display:flex;gap:4px;-webkit-box-align:center;-ms-flex-align:center;align-items:center}
nav.main-nav a{padding:10px 12px;border-radius:50px;font-weight:700;font-size:.9rem;color:#fff;white-space:nowrap}
nav.main-nav a:hover{background:rgba(255,255,255,.16);color:#fff}
.theme-toggle{width:52px;height:30px;border-radius:50px;border:1.5px solid rgba(255,255,255,.4);background:rgba(255,255,255,.15);position:relative;-ms-flex-negative:0;flex-shrink:0}
.theme-toggle:after{content:"\2600";position:absolute;top:2px;left:3px;width:22px;height:22px;border-radius:50%;background:var(--card);display:grid;place-items:center;font-size:12px;line-height:1;-webkit-transition:-webkit-transform .3s;transition:transform .3s;-webkit-box-shadow:0 2px 6px rgba(0,0,0,.2);box-shadow:0 2px 6px rgba(0,0,0,.2)}
[data-theme="dark"] .theme-toggle:after{content:"\263E";-webkit-transform:translateX(21px);transform:translateX(21px)}
.hamburger{display:none;font-size:1.5rem;color:#fff}

/* Hero */
.hero{position:relative;text-align:center;padding:84px 24px 70px;background:var(--sky);overflow:hidden}
.hero:before,.hero:after{content:"";position:absolute;border-radius:50%;background:radial-gradient(circle,rgba(47,107,255,.18),transparent 70%);pointer-events:none}
.hero:before{width:420px;height:420px;top:-160px;left:-120px}
.hero:after{width:520px;height:520px;bottom:-220px;right:-160px}
.pill-badge{display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:8px;background:var(--card);border:1px solid var(--line);padding:9px 20px;border-radius:50px;font-weight:700;font-size:.85rem;-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow);position:relative;z-index:2;animation:fadeUp .7s ease both}
.dot-live{width:9px;height:9px;border-radius:50%;background:#22C55E;-webkit-box-shadow:0 0 0 4px rgba(34,197,94,.2);box-shadow:0 0 0 4px rgba(34,197,94,.2);animation:pulse 1.6s infinite}
@keyframes pulse{50%{-webkit-box-shadow:0 0 0 8px rgba(34,197,94,0);box-shadow:0 0 0 8px rgba(34,197,94,0)}}
.hero h1{font-size:clamp(2.1rem,5.2vw,3.9rem);font-weight:800;line-height:1.12;margin:26px auto 18px;max-width:820px;position:relative;z-index:2;animation:fadeUp .7s .12s ease both}
.hero h1 em{font-style:normal;color:var(--royal);display:block}
.hero p{max-width:640px;margin:0 auto;color:var(--muted);font-size:1.05rem;line-height:1.7;position:relative;z-index:2;animation:fadeUp .7s .24s ease both}
.hero-btns{display:-webkit-box;display:-ms-flexbox;display:flex;gap:16px;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;margin-top:34px;position:relative;z-index:2;animation:fadeUp .7s .36s ease both;-ms-flex-wrap:wrap;flex-wrap:wrap}
.btn{padding:15px 34px;border-radius:50px;font-weight:800;font-size:.95rem;font-family:'Sora';display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:9px;-webkit-transition:-webkit-transform .25s;transition:transform .25s}
.btn svg{display:block}
.btn-primary{background:var(--grad);color:#fff;-webkit-box-shadow:var(--shadow-lg);box-shadow:var(--shadow-lg)}
.btn-primary:hover,.btn-ghost:hover{-webkit-transform:translateY(-3px);transform:translateY(-3px)}
.btn-ghost{background:var(--card);color:var(--ink);border:1.5px solid var(--line);-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow)}
@keyframes fadeUp{from{opacity:0;-webkit-transform:translateY(24px);transform:translateY(24px)}to{opacity:1;-webkit-transform:none;transform:none}}

/* Stats */
.stats{max-width:1180px;margin:-6px auto 0;padding:34px 24px 8px;display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.stat{border-radius:18px;padding:30px 20px;text-align:center;color:#fff;position:relative;overflow:hidden;-webkit-transition:-webkit-transform .3s;transition:transform .3s}
.stat:hover{-webkit-transform:translateY(-6px) scale(1.02);transform:translateY(-6px) scale(1.02)}
.stat-num{font-size:2.5rem;font-weight:800;position:relative;z-index:1}
.stat-lbl{font-size:.78rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;opacity:.92;position:relative;z-index:1;margin-top:4px}
.stat:nth-child(1){background:linear-gradient(135deg,#1E4FD8,#2F6BFF)}
.stat:nth-child(2){background:linear-gradient(135deg,#F97316,#FB923C)}
.stat:nth-child(3){background:linear-gradient(135deg,#16A34A,#22C55E)}
.stat:nth-child(4){background:linear-gradient(135deg,#DB2777,#EC4899)}


/* Hero Slider */
.hero-slider{max-width:1280px;margin:0 auto;padding:10px 24px 0}
.hs-wrap{position:relative;overflow:hidden;border-radius:24px;background:var(--card);border:1px solid var(--line);-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow)}
.hs-track{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-transition:-webkit-transform .55s cubic-bezier(.4,0,.2,1);transition:transform .55s cubic-bezier(.4,0,.2,1)}
.hs-slide{min-width:100%;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:30px;padding:44px 48px}
.hs-slide h3{font-size:clamp(1.3rem,2.6vw,1.9rem);font-weight:800;line-height:1.2;margin-bottom:12px}
.hs-slide h3 span{color:var(--royal)}
.hs-slide p{color:var(--muted);font-size:.98rem;max-width:480px;margin-bottom:22px}
.hs-art{-ms-flex-negative:0;flex-shrink:0;margin-left:auto}
.hs-art svg{width:110px;height:110px}
.hs-dots{display:-webkit-box;display:-ms-flexbox;display:flex;gap:8px;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;padding:16px 0 4px}
.hs-dot{width:9px;height:9px;border-radius:50%;background:var(--line);cursor:pointer;border:none;padding:0;-webkit-transition:all .3s;transition:all .3s}
.hs-dot.active{background:var(--royal);width:26px;border-radius:50px}
@media (max-width:700px){.hs-slide{padding:30px 24px;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;text-align:center}.hs-art{margin:0 auto}.hs-art svg{width:80px;height:80px}}

/* Section titles */
.section-head{text-align:center;padding:70px 24px 34px}
.section-head h2{font-size:clamp(1.6rem,3.4vw,2.3rem);font-weight:800}
.section-head p{color:var(--muted);margin-top:10px;font-size:.98rem}

/* Category pills */
.cats{max-width:1280px;margin:0 auto;padding:12px 24px;display:grid;grid-template-columns:repeat(12,1fr);gap:14px;position:sticky;top:73px;z-index:90;background:var(--bg);border-radius:0 0 18px 18px}
.cat-pill{background:var(--chip);border:1px solid var(--line);border-radius:16px;padding:18px 8px;text-align:center;-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow);-webkit-transition:all .28s;transition:all .28s;cursor:pointer}
.cat-pill:hover,.cat-pill.active{background:var(--grad);color:#fff;-webkit-transform:translateY(-5px);transform:translateY(-5px);-webkit-box-shadow:var(--shadow-lg);box-shadow:var(--shadow-lg);border-color:transparent}
.cat-ico{width:44px;height:44px;margin:0 auto 8px;border-radius:12px;background:var(--sky);border:1px solid var(--line);display:grid;place-items:center;font-family:'Sora';font-weight:800;font-size:1.05rem;color:var(--royal);overflow:hidden}
.cat-ico svg{width:32px;height:32px;display:block}
.cat-ico-img{padding:0}
.cat-ico-img img{width:100%;height:100%;object-fit:cover;display:block;border-radius:11px}
.cat-pill:hover .cat-ico,.cat-pill.active .cat-ico{background:rgba(255,255,255,.22);border-color:transparent;color:#fff}
.cat-pill .nm{font-size:.78rem;font-weight:800}
.cats-nav{display:-webkit-box;display:-ms-flexbox;display:flex;gap:12px;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;margin-top:22px}
.cats-nav button{width:44px;height:44px;border-radius:50%;border:1px solid var(--line);background:var(--card);color:var(--ink);font-size:1.1rem;-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow)}
.cats-nav button:hover{background:var(--royal);color:#fff}

/* Tool sections */
.tools-wrap{max-width:1280px;margin:0 auto;padding:0 24px 60px}
.tool-section{background:var(--card);border:1px solid var(--line);border-radius:18px;margin-top:26px;overflow:hidden;-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow)}
.tool-section.hidden-sec{display:none}
.sec-bar{background:var(--grad);color:#fff;padding:15px 26px;font-family:'Sora';font-weight:700;font-size:1.02rem;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:10px;position:relative;overflow:hidden}
.sec-bar:after{content:"";position:absolute;right:-28px;top:50%;-webkit-transform:translateY(-50%);transform:translateY(-50%);width:120px;height:120px;border-radius:50%;background:rgba(255,255,255,.14);pointer-events:none}
.sec-ico{width:28px;height:28px;border-radius:8px;background:rgba(255,255,255,.22);display:inline-grid;place-items:center;font-weight:800;font-size:.85rem;color:#fff}
.tool-grid{display:grid;grid-template-columns:repeat(5,1fr);padding:22px;gap:4px 14px}
.tool-link{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:11px;padding:11px 12px;border-radius:12px;font-size:.86rem;font-weight:600;-webkit-transition:background .22s;transition:background .22s}
.tool-link:hover{background:var(--sky);color:var(--royal)}
.tool-ico{width:34px;height:34px;border-radius:9px;-ms-flex-negative:0;flex-shrink:0;display:grid;place-items:center;background:var(--sky);border:1px solid var(--line);overflow:hidden}
.tool-ico svg{width:26px;height:26px;display:block}
.tool-ico img{width:100%;height:100%;object-fit:cover;display:block}
.no-results{text-align:center;padding:50px 20px;color:var(--muted);font-weight:700;display:none}

/* Blog / post pages */
.blog-posts{max-width:960px;margin:0 auto;padding:20px 24px 60px}
.tpw-post{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:26px;margin-bottom:24px;-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow)}
.post-title a{color:var(--ink)}
.post-title a:hover{color:var(--royal)}
.post-body{color:var(--ink);font-size:.98rem;line-height:1.8}
.post-body img{max-width:100%;height:auto;border-radius:12px}
.date-head{color:var(--muted);font-size:.8rem;font-weight:700;margin-bottom:8px}
.jump-link{font-weight:700;font-size:.85rem;color:var(--royal)}

/* Footer */
footer.tpw-footer{background:var(--grad);color:#fff;margin-top:60px}
.foot-grid{max-width:1280px;margin:0 auto;padding:60px 24px 30px;display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:40px}
.foot-grid h4{font-size:.8rem;letter-spacing:.16em;text-transform:uppercase;margin-bottom:18px}
.foot-grid a{display:block;padding:5px 0;font-size:.9rem;opacity:.88}
.foot-grid a:hover{opacity:1}
.foot-about p{font-size:.9rem;opacity:.9;line-height:1.7;margin:14px 0 18px;max-width:300px}
.socials{display:-webkit-box;display:-ms-flexbox;display:flex;gap:12px}
.socials a{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.16);font-size:1rem;padding:0}
.socials a svg{display:block;margin:auto}
.socials a:hover{background:rgba(255,255,255,.32)}
.foot-bottom{border-top:1px solid rgba(255,255,255,.2);text-align:center;padding:20px;font-size:.85rem;opacity:.85}

/* Back to top */
#toTop{position:fixed;right:24px;bottom:24px;z-index:90;width:50px;height:50px;border-radius:14px;background:var(--grad);color:#fff;font-size:1.3rem;-webkit-box-shadow:var(--shadow-lg);box-shadow:var(--shadow-lg);opacity:0;pointer-events:none;-webkit-transition:opacity .3s;transition:opacity .3s;-webkit-transform:translateY(14px);transform:translateY(14px)}
#toTop.show{opacity:1;pointer-events:auto;-webkit-transform:none;transform:none}


/* ====== STATIC + TOOL PAGES (Royal Blue) ====== */
.tool-page-wrap,.about-content,.contact-content,.privacy-content,.terms-content{max-width:960px;margin:0 auto}
.tool-hero{background:var(--sky);padding:44px 24px;text-align:center;border-bottom:1px solid var(--line)}
.tool-hero h1{font-family:'Sora';font-size:clamp(1.5rem,3.4vw,2.2rem);font-weight:800;color:var(--ink)}
.tool-hero p{color:var(--muted);margin-top:10px;font-size:.98rem;max-width:640px;margin-left:auto;margin-right:auto}
.tool-hero-inner{max-width:820px;margin:0 auto}
.tool-crumbs-wrap{background:var(--card);border-bottom:1px solid var(--line);padding:12px 0}
.tool-crumbs{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:8px;font-size:.82rem;font-weight:600;color:var(--muted);-ms-flex-wrap:wrap;flex-wrap:wrap}
.tool-crumbs a{color:var(--royal)}
.tool-crumbs a:hover{text-decoration:underline}
.crumb-sep{opacity:.6}
.tool-layout{display:grid;grid-template-columns:1fr 300px;gap:26px;padding:30px 0 50px}
.tool-main{min-width:0}
.tool-sidebar{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;gap:18px;-ms-flex-line-pack:start;align-content:flex-start}
.tool-card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:24px;-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow);margin-bottom:22px}
.tool-card-header{margin-bottom:16px}
.tool-card-title{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:10px;font-family:'Sora';font-weight:700;font-size:1.05rem;color:var(--ink)}
.tool-card-title svg{width:20px;height:20px;color:var(--royal);-ms-flex-negative:0;flex-shrink:0}
.tool-card-btn,.action-btn,.copy-btn,.clear-btn,.download-btn,.generate-btn,.add-item-btn,.copy-all-btn,.remove-btn,.alt-btn,.qr-btn,.pw-btn,.case-btn,.upload-zone,.btn{display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:8px;padding:11px 22px;border-radius:50px;font-weight:700;font-size:.86rem;border:1.5px solid var(--line);background:var(--card);color:var(--ink);cursor:pointer;-webkit-transition:all .25s;transition:all .25s;font-family:'Manrope'}
.tool-card-btn:hover,.action-btn:hover,.copy-btn:hover,.clear-btn:hover,.download-btn:hover,.generate-btn:hover,.add-item-btn:hover,.copy-all-btn:hover,.remove-btn:hover,.alt-btn:hover,.qr-btn:hover,.pw-btn:hover,.case-btn:hover{border-color:var(--royal);color:var(--royal)}
.primary,.pw-btn-primary,.generate-btn.primary{background:var(--grad);color:#fff !important;border-color:transparent}
.primary:hover,.pw-btn-primary:hover{color:#fff !important;-webkit-transform:translateY(-2px);transform:translateY(-2px)}
.pw-btn-secondary{background:var(--card)}
.btn-row,.preview-actions,.tool-card-actions,.tool-actions-bar,.uuid-actions,.pw-actions-row,.qr-btn-row,.wc-actions{display:-webkit-box;display:-ms-flexbox;display:flex;gap:10px;-ms-flex-wrap:wrap;flex-wrap:wrap;margin-top:16px}
.tool-textarea,.form-textarea,.bulk-area,.output-area,.output-code,.output-dark textarea,textarea.tool-textarea{width:100%;min-height:180px;padding:14px;border:1.5px solid var(--line);border-radius:12px;font:500 .92rem 'Manrope';color:var(--ink);background:var(--bg);resize:vertical;outline:none;font-family:'Manrope'}
.tool-textarea:focus,.form-textarea:focus{border-color:var(--royal)}
.form-group{margin-bottom:16px}
.form-label{display:block;font-weight:700;font-size:.84rem;margin-bottom:6px;color:var(--ink)}
.form-input,.form-select{width:100%;padding:11px 14px;border:1.5px solid var(--line);border-radius:10px;font:500 .9rem 'Manrope';color:var(--ink);background:var(--bg);outline:none}
.form-input:focus,.form-select:focus{border-color:var(--royal)}
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.output-box,.result-box,.result-card,.result-output,.hash-result{background:var(--sky);border:1px solid var(--line);border-radius:12px;padding:16px;margin-top:14px;font-family:'Manrope'}
.result-content{word-break:break-all}
.output-badge,.output-badges span,.chip{display:inline-block;background:var(--card);border:1px solid var(--line);border-radius:50px;padding:4px 14px;font-size:.75rem;font-weight:700;color:var(--royal);margin:2px}
.stats-grid,.info-grid,.features-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}
.stats-row{display:-webkit-box;display:-ms-flexbox;display:flex;gap:14px;-ms-flex-wrap:wrap;flex-wrap:wrap;margin:14px 0}
.stat-card,.stat-box,.info-card{background:var(--sky);border:1px solid var(--line);border-radius:12px;padding:14px;text-align:center;-webkit-box-flex:1;-ms-flex:1;flex:1;min-width:100px}
.stat-card .stat-num,.stat-box .stat-num,.info-card .stat-num,.stat-val,.stat-value{font-family:'Sora';font-weight:800;font-size:1.3rem;color:var(--royal)}
.stat-card .stat-lbl,.stat-box .stat-lbl,.info-card .stat-lbl,.stat-label{font-size:.7rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-top:3px}
.stat-label-icon{display:inline-block}
.feature-card,.howto-card,.advice-card,.privacy-card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px;-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow)}
.feature-icon,.advice-icon,.info-icon,.howto-card svg{width:36px;height:36px;border-radius:10px;background:var(--sky);border:1px solid var(--line);display:grid;place-items:center;color:var(--royal);margin-bottom:10px}
.feature-card h4,.howto-card h4,.advice-card h4{font-family:'Sora';font-size:.95rem;margin-bottom:6px;color:var(--ink)}
.feature-card p,.howto-card p,.advice-card p,.advice-text{font-size:.86rem;color:var(--muted)}
.howto-steps{counter-reset:step;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;gap:12px}
.features-section,.info-section{margin:26px 0}
.features-title{font-family:'Sora';font-weight:800;font-size:1.15rem;margin-bottom:14px;color:var(--ink)}
.about-content,.contact-content,.privacy-content,.terms-content{padding:34px 24px 50px}
.about-section,.privacy-section,.terms-section{margin-bottom:26px}
.about-section h2,.privacy-section h2,.terms-section h2{font-family:'Sora';font-weight:800;font-size:1.25rem;color:var(--ink);margin-bottom:10px}
.about-section p,.privacy-section p,.terms-section p,.about-section li,.privacy-section li,.terms-section li{color:var(--muted);font-size:.95rem;line-height:1.8;margin-bottom:10px}
.about-section ul,.privacy-section ul,.terms-section ul{list-style:disc;padding-left:22px}
.about-section strong,.privacy-section strong,.terms-section strong{color:var(--ink)}
.about-section a,.privacy-section a,.terms-section a{color:var(--royal)}
.table-wrap{overflow-x:auto;margin:14px 0}
.table-wrap table,.kw-table,.rank-table{width:100%;border-collapse:collapse;font-size:.88rem}
.table-wrap th,.table-wrap td,.kw-table th,.kw-table td,.rank-table th,.rank-table td{padding:10px 12px;border:1px solid var(--line);text-align:left}
.table-wrap th,.kw-table th,.rank-table th{background:var(--sky);font-weight:700;color:var(--ink)}
.checkbox-group,.pw-checkboxes{display:-webkit-box;display:-ms-flexbox;display:flex;-ms-flex-wrap:wrap;flex-wrap:wrap;gap:10px;margin:10px 0}
.checkbox-item,.pw-checkbox-item{display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:7px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:8px 14px;font-size:.85rem;cursor:pointer}
.pw-checkbox-label{cursor:pointer}
.upload-zone{border:2px dashed var(--line);border-radius:14px;padding:34px;text-align:center;cursor:pointer;-webkit-transition:border-color .3s;transition:border-color .3s;width:100%;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center}
.upload-zone:hover{border-color:var(--royal)}
.upload-icon svg{width:42px;height:42px;color:var(--royal);margin:0 auto 10px}
.upload-text{font-weight:700;color:var(--ink);font-size:.95rem}
.upload-hint{font-size:.8rem;color:var(--muted);margin-top:4px}
.badge-good,.badge-ok,.ok,.status-badge.ok{background:#DCFCE7;color:#16A34A;border-radius:50px;padding:3px 12px;font-size:.75rem;font-weight:700}
.badge-warn,.badge-medium{background:#FEF3C7;color:#D97706;border-radius:50px;padding:3px 12px;font-size:.75rem;font-weight:700}
.badge-bad,.error,.status-badge.error{background:#FEE2E2;color:#DC2626;border-radius:50px;padding:3px 12px;font-size:.75rem;font-weight:700}
.error-msg{color:#DC2626;font-size:.84rem;font-weight:600;margin-top:8px}
.empty-state{text-align:center;color:var(--muted);padding:30px;font-size:.9rem}
.score-bar,.kw-bar,.strength-bar-wrap{background:var(--line);border-radius:50px;height:8px;overflow:hidden;margin-top:8px}
.score-fill,.kw-bar-fill,.strength-bar{height:100%;background:var(--grad);border-radius:50px;-webkit-transition:width .6s;transition:width .6s}
.loading{text-align:center;padding:20px;color:var(--muted);font-weight:600}
.muted{color:var(--muted)}
.char-count{font-size:.78rem;color:var(--muted);text-align:right;margin-top:6px}
@media (max-width:900px){
 .tool-layout{grid-template-columns:1fr}
 .tool-sidebar{-webkit-box-orient:horizontal;-webkit-box-direction:normal;-ms-flex-direction:row;flex-direction:row;overflow-x:auto}
 .stats-grid,.info-grid,.features-grid{grid-template-columns:1fr 1fr}
 .form-row{grid-template-columns:1fr}
}
@media (max-width:560px){
 .stats-grid,.info-grid,.features-grid{grid-template-columns:1fr}
 .tool-card{padding:18px}
}


/* ====== TOOL PAGES COMPAT (aliases + missing classes) ====== */
.container{max-width:1180px;margin:0 auto;padding:0 20px}
.form-body{padding:4px 0}
.crumb-cat{font-weight:700}
.action-pill{display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:7px;padding:10px 18px;border-radius:50px;border:1.5px solid var(--line);background:var(--card);color:var(--ink);font:700 .84rem 'Manrope';cursor:pointer;-webkit-transition:all .25s;transition:all .25s}
.action-pill:hover{border-color:var(--royal);color:var(--royal)}
.action-pill.primary{background:var(--grad);color:#fff;border-color:transparent}
.action-pill svg{width:15px;height:15px}
.stat-row .stat-card,.stat-row .stat-box{min-width:140px}
.feature-icon.blue,.info-icon.blue,.stat-label-icon.blue{background:#DBEAFE;color:#2563EB}
.feature-icon.green,.info-icon.green,.stat-label-icon.green{background:#DCFCE7;color:#16A34A}
.feature-icon.purple,.info-icon.purple,.stat-label-icon.purple{background:#F3E8FF;color:#9333EA}
.feature-icon.red,.info-icon.red,.stat-label-icon.red{background:#FEE2E2;color:#DC2626}
.feature-icon.orange,.info-icon.orange,.stat-label-icon.orange{background:#FFEDD5;color:#EA580C}
.feature-icon.teal,.info-icon.teal,.stat-label-icon.teal{background:#CCFBF1;color:#0D9488}
.feature-icon.amber,.info-icon.amber,.stat-label-icon.amber{background:#FEF3C7;color:#D97706}
.feature-icon.pink,.info-icon.pink,.stat-label-icon.pink{background:#FCE7F3;color:#DB2777}
.feature-icon.indigo,.info-icon.indigo,.stat-label-icon.indigo{background:#E0E7FF;color:#4F46E5}
.feature-icon.cyan,.info-icon.cyan,.stat-label-icon.cyan{background:#CFFAFE;color:#0891B2}
.feature-icon.lime,.info-icon.lime,.stat-label-icon.lime{background:#ECFCCB;color:#65A30D}
.feature-icon.slate,.info-icon.slate,.stat-label-icon.slate{background:#F1F5F9;color:#475569}
.feature-icon.darkgreen,.info-icon.darkgreen,.stat-label-icon.darkgreen{background:#D1FAE5;color:#047857}
.feature-icon,.info-icon,.stat-label-icon{font-weight:800;font-size:.9rem}
/* Password Generator */
.pw-output{position:relative}
.pw-display{width:100%;padding:16px 52px 16px 16px;border:1.5px solid var(--line);border-radius:12px;background:var(--sky);font:700 1.05rem ui-monospace,monospace;color:var(--ink);word-break:break-all;min-height:54px}
.pw-length-row{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:14px;margin:16px 0}
.pw-length-label{font-weight:700;font-size:.86rem}
.pw-length-value{font-family:'Sora';font-weight:800;color:var(--royal);min-width:32px;text-align:center}
.pw-slider{-webkit-box-flex:1;-ms-flex:1;flex:1;accent-color:#2F6BFF}
.pw-options{margin:10px 0}
.pw-check-icon{width:16px;height:16px;color:var(--royal)}
.strength-card{margin-top:16px}
.strength-meta{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-pack:justify;-ms-flex-pack:justify;justify-content:space-between;font-size:.8rem;font-weight:700;color:var(--muted);margin-bottom:4px}
.strength-score{color:var(--royal);font-family:'Sora'}
.strength-label{font-weight:800;font-size:.85rem}
/* QR Generator */
.qr-layout{display:grid;grid-template-columns:1fr 260px;gap:22px;-webkit-box-align:start;-ms-flex-align:start;align-items:start}
.qr-output{text-align:center}
.qr-code-container{display:inline-block;padding:16px;background:#fff;border:1px solid var(--line);border-radius:14px}
.qr-download-info{font-size:.78rem;color:var(--muted);margin-top:10px}
@media (max-width:700px){.qr-layout{grid-template-columns:1fr}}
/* UUID */
.uuid-list{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;gap:8px;margin-top:12px}
.uuid-text{font-family:ui-monospace,monospace;font-size:.86rem;background:var(--sky);border:1px solid var(--line);border-radius:8px;padding:9px 12px;word-break:break-all;color:var(--ink)}
/* JSON viewer */
.json-tree{font-family:ui-monospace,monospace;font-size:.84rem;line-height:1.7;overflow-x:auto}
.jv-block{padding-left:20px}
.jv-key{color:#9333EA;font-weight:700}
.jv-str{color:#16A34A}
.jv-num{color:#2563EB}
.jv-bool{color:#EA580C}
.jv-null{color:#94A3B8}
.jv-punct{color:var(--muted)}
/* Open Graph / Twitter previews */
.og-preview{max-width:460px;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--card)}
.og-preview-img{height:0;padding-top:52%;background:var(--sky) center/cover no-repeat}
.og-preview-body{padding:12px 14px}
.og-preview-domain{font-size:.72rem;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}
.og-preview-title{font-weight:800;font-size:.95rem;color:var(--ink);margin:3px 0}
.og-preview-desc{font-size:.82rem;color:var(--muted);line-height:1.45}
.preview-box{margin-top:14px}
.preview-frame{border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--card)}
.preview-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.card-preview{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px}
@media (max-width:640px){.preview-grid{grid-template-columns:1fr}}
/* Invoice generator */
.item-qty,.item-price{width:70px}
.item-desc{width:100%}
.item-total{font-weight:700;white-space:nowrap}
.item-remove{background:none;border:none;color:#DC2626;cursor:pointer;font-size:1rem;padding:4px}
.totals-box{margin-left:auto;max-width:280px;margin-top:14px}
.totals-row{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-pack:justify;-ms-flex-pack:justify;justify-content:space-between;padding:7px 0;font-size:.9rem;border-bottom:1px dashed var(--line)}
.totals-row.total{font-weight:800;font-size:1.05rem;color:var(--royal);border-bottom:none;border-top:2px solid var(--line)}
/* Hash generator */
.hash-result{margin-top:14px}
.hash-label{font-size:.72rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.hash-value{font-family:ui-monospace,monospace;font-size:.82rem;word-break:break-all;color:var(--ink);margin-top:3px}
/* Misc tool bits */
.mode-option{display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:7px;padding:9px 16px;border:1.5px solid var(--line);border-radius:10px;cursor:pointer;font-weight:600;font-size:.85rem;background:var(--bg)}
.mode-option.active{border-color:var(--royal);color:var(--royal);background:var(--sky)}
.chain-item{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:10px}
.chain-arrow{color:var(--muted);text-align:center;font-size:1.1rem}
.thumb-card{position:relative;border-radius:12px;overflow:hidden;border:1px solid var(--line)}
.barcode-preview{background:#fff;padding:18px;border-radius:12px;border:1px solid var(--line);text-align:center}
.diff-line{font-family:ui-monospace,monospace;font-size:.84rem;padding:3px 10px;border-radius:6px}
.diff-same{color:var(--muted)}
.chk{width:16px;height:16px;accent-color:#2F6BFF}
.checkbox-item.checked{border-color:var(--royal);background:var(--sky)}
.action-col{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;gap:8px}
.add-path,.path-remove{padding:8px 14px;font-size:.8rem}
.path-row{display:-webkit-box;display:-ms-flexbox;display:flex;gap:8px;margin-bottom:8px}
.path-row .form-input{-webkit-box-flex:1;-ms-flex:1;flex:1}
.output-body{padding:6px 0}
.feature-icon.blue svg,.feature-icon.green svg,.feature-icon.purple svg,.feature-icon.red svg,.feature-icon.orange svg,.feature-icon.teal svg,.feature-icon.amber svg,.feature-icon.pink svg,.feature-icon.indigo svg,.feature-icon.cyan svg,.feature-icon.lime svg,.feature-icon.slate svg,.feature-icon.darkgreen svg{width:18px;height:18px}


/* Sidebar list buttons + info alignment */
.tool-sidebar .case-btn,.case-btn{display:-webkit-box;display:-ms-flexbox;display:flex;width:100%;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:justify;-ms-flex-pack:justify;justify-content:space-between;padding:12px 16px;border-radius:12px;border:1.5px solid var(--line);background:var(--bg);color:var(--ink);font:700 .86rem 'Manrope';cursor:pointer;margin-bottom:8px;-webkit-transition:all .25s;transition:all .25s}
.case-btn:hover{border-color:var(--royal);color:var(--royal)}
.case-btn.active{background:var(--grad);color:#fff;border-color:transparent}
.case-btn svg{width:16px;height:16px;-ms-flex-negative:0;flex-shrink:0}
.info-card{text-align:left}
.info-card h3{font-family:'Sora';font-weight:700;font-size:.95rem;color:var(--ink);margin-bottom:6px}
.info-card p{font-size:.85rem;color:var(--muted);line-height:1.6}


/* Button SVG sizing */
.pw-btn svg,.action-btn svg,.tool-card-btn svg,.btn svg,.action-pill svg,.copy-btn svg,.clear-btn svg,.download-btn svg,.alt-btn svg,.qr-btn svg,.case-btn svg,.add-item-btn svg,.remove-btn svg,.copy-all-btn svg{width:16px;height:16px;-ms-flex-negative:0;flex-shrink:0}
.pw-btn{border-radius:14px}
.pw-check-icon{display:none}
.pw-checkbox-item input{accent-color:#2F6BFF}

@media (min-width:1280px){
 .nav-wrap{position:relative}
 .search-box{position:absolute;left:50%;top:50%;-webkit-transform:translate(-50%,-50%);transform:translate(-50%,-50%);width:440px;max-width:none;margin:0;z-index:1}
 nav.main-nav{margin-left:auto}
}

/* Blogger admin toolbar (owner-only) */
#navbarContainer,#b-navbar,.navbar-blogger,#bAdminTopbar,body > iframe[src*="b-navbar"],body > iframe[src*="navbar"]{display:none !important}

/* Responsive */
@media (max-width:1080px){
 .cats{grid-template-columns:repeat(6,1fr)}
 .tool-grid{grid-template-columns:repeat(3,1fr)}
 .foot-grid{grid-template-columns:1fr 1fr}
}
@media (max-width:820px){
 .hamburger{display:block;margin-left:auto}
 nav.main-nav{display:none;position:absolute;top:100%;left:0;right:0;background:var(--card);-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;-webkit-box-align:stretch;-ms-flex-align:stretch;align-items:stretch;padding:14px;border-bottom:1px solid var(--line);gap:4px;-webkit-box-shadow:var(--shadow-lg);box-shadow:var(--shadow-lg)}
 nav.main-nav.open{display:-webkit-box;display:-ms-flexbox;display:flex}
 nav.main-nav a{text-align:center;color:var(--ink)}
 .stats{grid-template-columns:repeat(2,1fr)}
 .search-box{-webkit-box-ordinal-group:4;-ms-flex-order:3;order:3;max-width:100%;-ms-flex-preferred-size:100%;flex-basis:100%;margin:0}
 .cats{top:139px}
 .nav-wrap{-ms-flex-wrap:wrap;flex-wrap:wrap}
}
@media (max-width:600px){
 .cats{grid-template-columns:repeat(4,1fr)}
 .tool-grid{grid-template-columns:repeat(2,1fr);padding:14px}
 .foot-grid{grid-template-columns:1fr;gap:30px;padding:44px 24px 20px}
 .hero{padding:60px 18px 54px}
 .btn{padding:13px 26px}
}
@media (max-width:400px){
 .cats{grid-template-columns:repeat(3,1fr)}
 .tool-grid{grid-template-columns:1fr 1fr}
 .stat-num{font-size:1.9rem}
}

body.script:
//
function selectCategory(target, el){
  var pills = document.querySelectorAll('.cat-pill');
  pills.forEach(function(p){ p.classList.remove('active'); });
  el.classList.add('active');
  document.querySelectorAll('.tool-section').forEach(function(sec){
    sec.classList.toggle('hidden-sec', target !== 'all' && sec.id !== 'sec-' + target);
  });
  var s = document.getElementById('toolSearch'); if (s) s.value = '';
  var n = document.getElementById('noResults'); if (n) n.style.display = 'none';
  var t = document.getElementById('all-tools'); if (t) t.scrollIntoView({behavior:'smooth'});
}
function shiftCats(dir){
  var g = document.getElementById('catGrid'); if (g) g.scrollBy({left: dir * 300, behavior:'smooth'});
}
function filterTools(q){
  q = q.trim().toLowerCase();
  var any = false;
  document.querySelectorAll('.tool-section').forEach(function(sec){
    var visible = 0;
    sec.querySelectorAll('.tool-link').forEach(function(l){
      var hit = !q || l.getAttribute('data-name').indexOf(q) > -1;
      l.style.display = hit ? 'flex' : 'none';
      if (hit) visible++;
    });
    sec.classList.toggle('hidden-sec', visible === 0);
    if (visible > 0) any = true;
  });
  var n = document.getElementById('noResults'); if (n) n.style.display = any ? 'none' : 'block';
  if (q) document.querySelectorAll('.cat-pill').forEach(function(p){ p.classList.remove('active'); });
}
function toggleTheme(){
  var html = document.documentElement;
  var next = html.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
  html.setAttribute('data-theme', next);
  try { localStorage.setItem('tpw-theme', next); } catch(e){}
}
(function(){
  var saved = null;
  try { saved = localStorage.getItem('tpw-theme'); } catch(e){}
  var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  document.documentElement.setAttribute('data-theme', saved || (prefersDark ? 'dark' : 'light'));
})();
window.addEventListener('scroll', function(){
  var b = document.getElementById('toTop');
  if (b) b.classList.toggle('show', window.scrollY > 400);
});

/* Animated stat counters */
(function(){
  var nums = document.querySelectorAll('.stat-num[data-count]');
  if (!nums.length) return;
  function animate(el){
    var target = parseInt(el.getAttribute('data-count'), 10);
    var prefix = el.getAttribute('data-prefix') || '';
    var suffix = el.getAttribute('data-suffix') || '';
    var dur = 1600, start = null;
    function step(ts){
      if (!start) start = ts;
      var p = Math.min((ts - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = prefix + Math.round(target * eased) + suffix;
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting) { animate(e.target); io.unobserve(e.target); }
      });
    }, {threshold: 0.4});
    nums.forEach(function(n){ io.observe(n); });
  } else {
    nums.forEach(animate);
  }
})();

/* Hero slider */
(function(){
  var track = document.getElementById('hsTrack');
  if (!track) return;
  var dotsWrap = document.getElementById('hsDots');
  var total = track.children.length;
  var cur = 0, timer = null;
  for (var i = 0; i < total; i++) {
    var b = document.createElement('button');
    b.className = 'hs-dot' + (i === 0 ? ' active' : '');
    b.setAttribute('aria-label', 'Slide ' + (i + 1));
    (function(idx){ b.onclick = function(){ go(idx); reset(); }; })(i);
    dotsWrap.appendChild(b);
  }
  function go(n){
    cur = (n + total) % total;
    track.style.transform = 'translateX(-' + (cur * 100) + '%)';
    var ds = dotsWrap.children;
    for (var i = 0; i < ds.length; i++) ds[i].classList.toggle('active', i === cur);
  }
  function next(){ go(cur + 1); }
  function reset(){ clearInterval(timer); timer = setInterval(next, 4500); }
  reset();
})();
var menu = document.getElementById('mainNav');
if (menu) menu.querySelectorAll('a').forEach(function(a){
  a.addEventListener('click', function(){ menu.classList.remove('open'); });
});
//
